package android.graphics;public class Color {public static final int BLACK=0xff000000,WHITE=0xffffffff,DKGRAY=0xff444444;public static int red(int c){return c>>16&255;}public static int green(int c){return c>>8&255;}public static int blue(int c){return c&255;}public static int rgb(int r,int g,int b){return 0xff000000|r<<16|g<<8|b;}}